"use client";

import {
  createContext,
  useCallback,
  useContext,
  useRef,
  useState,
} from "react";
import { useRouter } from "next/navigation";
import {
  PremiumUpgradeDialog,
  type PremiumPrice,
  type UpgradeFeature,
} from "./premium-upgrade-dialog";
import { useWorkspaceEntitlements } from "./workspace-quota";

type OpenUpgrade = (options?: {
  feature?: UpgradeFeature;
  trigger?: HTMLElement | null;
}) => void;
const UpgradeContext = createContext<OpenUpgrade | null>(null);

export function PremiumUpgradeProvider({
  children,
  premiumPrice,
}: {
  children: React.ReactNode;
  premiumPrice: PremiumPrice;
}) {
  const access = useWorkspaceEntitlements();
  const [feature, setFeature] = useState<UpgradeFeature | undefined>(undefined);
  const [isOpen, setIsOpen] = useState(false);
  const returnFocusRef = useRef<HTMLElement | null>(null);
  const open = useCallback<OpenUpgrade>(
    ({ feature: name, trigger } = {}) => {
      if (
        access.effectivePlan !== "FREE" ||
        !access.controlsAvailable ||
        access.reasons.send === "ACCOUNT_SUSPENDED" ||
        access.reasons.send === "ACCOUNT_UNAVAILABLE"
      )
        return;
      returnFocusRef.current =
        trigger ??
        (document.activeElement instanceof HTMLElement
          ? document.activeElement
          : null);
      setFeature(name);
      setIsOpen(true);
    },
    [access],
  );

  return (
    <UpgradeContext value={open}>
      {children}
      {isOpen && (
        <PremiumUpgradeDialog
          reason={feature === "allowance" ? "allowance" : "feature"}
          feature={feature}
          premiumPrice={premiumPrice}
          returnFocusRef={returnFocusRef}
          onClose={() => setIsOpen(false)}
        />
      )}
    </UpgradeContext>
  );
}

export function usePremiumUpgrade(fallback?: OpenUpgrade): OpenUpgrade {
  const open = useContext(UpgradeContext);
  const router = useRouter();
  // Public and admin appearance menus also use this control, outside the workspace.
  return open ?? fallback ?? (() => router.push("/usage"));
}
